      session: 'shared',
      workspace: 'shared',
    }),
    grants: Object.freeze([
      Object.freeze({ resource: 'run-output', access: 'write', scope: 'dispatch' }),
      Object.freeze({ resource: 'private-home', access: 'read-write', scope: 'dispatch' }),
